import { mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, utimesSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import type { RunSnapshot } from './adapter.ts';
import { FileRunStore, KEEP_RUNS } from './adapter.ts';

let directory: string;
let errors: string[];
let store: FileRunStore;

function snapshot( overrides: Partial<RunSnapshot> = {} ): RunSnapshot {
	return {
		id: randomUUID(),
		stageId: 'prep',
		version: '4.17.5',
		prompt: '/wpsp-prep-release 4.17.5',
		status: 'done',
		error: null,
		startedAt: 1000,
		endedAt: 2000,
		sessionId: 'session-1',
		costUsd: 0.5,
		files: [ '/repo/readme.txt' ],
		items: [ { kind: 'system', id: 'i', text: 'Session started.' } ],
		gates: [],
		resumedFrom: null,
		outcome: null,
		...overrides,
	};
}

beforeEach( () => {
	directory = path.join( mkdtempSync( path.join( tmpdir(), 'release-console-store-' ) ), 'runs' );
	errors = [];
	store = new FileRunStore( directory, ( message ) => errors.push( message ) );
} );

afterEach( () => {
	rmSync( path.dirname( directory ), { recursive: true, force: true } );
} );

describe( 'FileRunStore', () => {
	it( 'creates its folder and round-trips a run', () => {
		const run = snapshot();

		store.save( run );

		expect( store.loadAll() ).toEqual( [ run ] );
		expect( readdirSync( directory ) ).toEqual( [ `${ run.id }.json` ] );
	} );

	it( 'never saves pending gates', () => {
		const run = snapshot( {
			status: 'waiting',
			gates: [ { id: 'g', type: 'approval', createdAt: 1, subagent: false, toolName: 'Bash', command: 'git push', reason: 'r', title: null, confirmPhrase: null } ],
		} );

		store.save( run );

		expect( JSON.parse( readFileSync( path.join( directory, `${ run.id }.json` ), 'utf8' ) ).gates ).toEqual( [] );
	} );

	it( 'loads a run that was active when the server stopped as interrupted', () => {
		for ( const status of [ 'running', 'waiting', 'awaiting_reply' ] as const ) {
			store.save( snapshot( { status, endedAt: null, startedAt: 5 } ) );
		}

		for ( const run of store.loadAll() ) {
			expect( run ).toMatchObject( { status: 'interrupted', endedAt: 5 } );
		}
	} );

	it( 'loads a run that was only waiting to be closed after reporting success as done', () => {
		store.save( snapshot( { status: 'awaiting_reply', endedAt: null, startedAt: 7, outcome: { status: 'ok', summary: '', files: [], followups: [] } } ) );
		store.save( snapshot( { status: 'awaiting_reply', endedAt: null, startedAt: 6, outcome: { status: 'blocked', summary: '', files: [], followups: [] } } ) );

		expect( store.loadAll().map( ( run ) => run.status ) ).toEqual( [ 'done', 'interrupted' ] );
	} );

		it( 'loads newest first', () => {
		store.save( snapshot( { startedAt: 1 } ) );
		store.save( snapshot( { startedAt: 3 } ) );
		store.save( snapshot( { startedAt: 2 } ) );

		expect( store.loadAll().map( ( run ) => run.startedAt ) ).toEqual( [ 3, 2, 1 ] );
	} );

	it( 'skips corrupt and unrecognised files, and reports them', () => {
		mkdirSync( directory, { recursive: true } );
		writeFileSync( path.join( directory, 'broken.json' ), '{nope' );
		writeFileSync( path.join( directory, 'wrong.json' ), JSON.stringify( { id: 'not-a-uuid' } ) );
		writeFileSync( path.join( directory, 'bad-status.json' ), JSON.stringify( snapshot( { status: 'exploded' as never } ) ) );
		writeFileSync( path.join( directory, 'notes.txt' ), 'ignored' );
		store.save( snapshot() );

		expect( store.loadAll() ).toHaveLength( 1 );
		expect( errors ).toHaveLength( 3 );
	} );

	it( 'fills in missing optional fields from older saves', () => {
		const { resumedFrom, sessionId, costUsd, error, ...old } = snapshot();
		mkdirSync( directory, { recursive: true } );
		writeFileSync( path.join( directory, `${ old.id }.json` ), JSON.stringify( old ) );

		expect( store.loadAll()[ 0 ] ).toMatchObject( { resumedFrom: null, sessionId: null, costUsd: null, error: null } );
		void [ resumedFrom, sessionId, costUsd, error ];
	} );

	it( 'returns nothing when the folder does not exist', () => {
		expect( store.loadAll() ).toEqual( [] );
	} );

	it( 'refuses to save a run whose id could escape the folder', () => {
		store.save( snapshot( { id: '../../evil' } ) );

		expect( store.loadAll() ).toEqual( [] );
	} );

	it( `keeps only the newest ${ KEEP_RUNS } runs`, () => {
		const runs = Array.from( { length: KEEP_RUNS + 2 }, ( _, i ) => snapshot( { startedAt: i } ) );

		runs.forEach( ( run, i ) => {
			store.save( run );
			// Give each file a distinct, increasing modification time.
			const seconds = 1_700_000_000 + i;
			utimesSync( path.join( directory, `${ run.id }.json` ), seconds, seconds );
		} );

		store.save( runs[ runs.length - 1 ] );

		const kept = readdirSync( directory );

		expect( kept ).toHaveLength( KEEP_RUNS );
		expect( kept ).not.toContain( `${ runs[ 0 ].id }.json` );
		expect( kept ).not.toContain( `${ runs[ 1 ].id }.json` );
	} );

	it( 'reports a save it could not make instead of throwing', () => {
		writeFileSync( path.join( path.dirname( directory ), 'runs' ), 'a file where the folder should be' );

		expect( () => store.save( snapshot() ) ).not.toThrow();
		expect( errors[ 0 ] ).toMatch( /Could not save run/ );
	} );
} );
